package net.hivel.islandsrpg.visual;
import net.hivel.islandsrpg.IslandsRPGPlugin; import net.hivel.islandsrpg.magic.MagicItemDefinition; import net.hivel.islandsrpg.weapon.WeaponDefinition; import org.bukkit.Location; import org.bukkit.entity.*; import org.bukkit.scheduler.BukkitTask; import java.util.*;
public class ParticleService { private final IslandsRPGPlugin plugin; private BukkitTask task; private int tick; public ParticleService(IslandsRPGPlugin p){plugin=p;} public void start(){stop(); task=plugin.getServer().getScheduler().runTaskTimer(plugin,this::tick,1,1);} public void stop(){if(task!=null)task.cancel();} private boolean can(Player p, boolean javaOnly){if(plugin.floodgate().isBedrock(p)) return plugin.getConfig().getBoolean("visuals.bedrock-particles",false)&&!javaOnly; return plugin.getConfig().getBoolean("visuals.java-particles",true);} private void tick(){tick++; int max=plugin.getConfig().getInt("visuals.max-held-particle-items-per-tick",50), count=0; for(Player p:plugin.getServer().getOnlinePlayers()){if(count++>=max)break; var hand=p.getInventory().getItemInMainHand(); WeaponDefinition w=plugin.weapons().from(hand); if(w!=null&&w.heldEnabled()&&tick%Math.max(1,w.heldInterval())==0&&can(p,w.heldJavaOnly())) spawnAround(p,w.heldParticle(),w.heldCount(),w.heldRadius()); MagicItemDefinition m=plugin.magic().from(hand); if(m!=null&&m.heldEnabled()&&tick%Math.max(1,m.heldInterval())==0&&can(p,m.heldJavaOnly())) spawnAround(p,m.heldParticle(),m.heldCount(),m.heldRadius());}} private void spawnAround(Player p, org.bukkit.Particle particle,int count,double radius){Location l=p.getLocation().add(0,1,0); p.getWorld().spawnParticle(particle,l,count,radius,.4,radius);} public void hit(Player p, LivingEntity target, WeaponDefinition w){if(w.hitEnabled()&&can(p,w.hitJavaOnly())) target.getWorld().spawnParticle(w.hitParticle(),target.getLocation().add(0,1,0),w.hitCount(),.4,.4,.4);} public void hit(Player p, LivingEntity target, MagicItemDefinition m){if(m.hitEnabled()&&can(p,m.hitJavaOnly())) target.getWorld().spawnParticle(m.hitParticle(),target.getLocation().add(0,1,0),m.hitCount(),.4,.4,.4);} }
